// Standalone prototype: all data stays in memory and resets on reload.
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',transactions:'M7 3h10l3 3v15H4V3h3 M8 9h8 M8 13h8 M8 17h5',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',reports:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16V9',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',arrow:'M7 17 17 7 M7 7h10v10',wallet:'M3 5h17v15H3z M15 10h6v6h-6z',back:'m14 6-6 6 6 6',print:'M6 9V3h12v6 M6 18H3V9h18v9h-3 M6 14h12v7H6z'};
const icon=k=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[k]||paths.transactions}"/></svg>`;
const money=n=>new Intl.NumberFormat('vi-VN').format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const customers=[{id:1,name:'Nguyễn Văn Bình',phone:'0900 123 456',address:'Ấp Tân Phú, xã Tân Hiệp',initials:'NB'},{id:2,name:'Trần Thị Hương',phone:'0912 345 678',address:'Ấp Bình Hòa, xã Tân Hiệp',initials:'TH'},{id:3,name:'Lê Hoàng Nam',phone:'0934 567 890',address:'Ấp Tân Lợi, xã Tân Hiệp',initials:'LN'},{id:4,name:'Phạm Thị Lan',phone:'0987 654 321',address:'Ấp Phú Thuận, xã Tân Hiệp',initials:'PL'},{id:5,name:'Võ Minh Tuấn',phone:'0908 111 222',address:'Ấp Tân Phú, xã Tân Hiệp',initials:'VT'}];
let transactions=[{id:1026,c:1,date:'2026-11-02',type:'Mua hàng',content:'Phân bón NPK 20-20-15 · 10 bao',amount:8500000,interest:0,paid:false},{id:1025,c:2,date:'2026-11-01',type:'Tiền mặt',content:'Vay tiền chăm sóc vườn đầu vụ',amount:20000000,interest:0,paid:false},{id:1024,c:3,date:'2026-10-22',type:'Chuyển khoản',content:'Ứng tiền mua vật tư nông nghiệp',amount:15000000,interest:110000,paid:false},{id:1023,c:1,date:'2026-10-02',type:'Tiền mặt',content:'Vay tiền đầu vụ',amount:30000000,interest:600000,paid:false},{id:1022,c:4,date:'2026-10-02',type:'Mua hàng',content:'Thuốc bảo vệ thực vật · Đơn hàng 125',amount:6400000,interest:96000,paid:false},{id:1021,c:5,date:'2026-09-15',type:'Mua hàng',content:'Phân bón hữu cơ · 20 bao',amount:12000000,interest:180000,paid:true},{id:1020,c:2,date:'2026-09-02',type:'Chuyển khoản',content:'Ứng trước chi phí thu hoạch',amount:25000000,interest:1000000,paid:false}];
const navItems=[['overview','Tổng quan'],['transactions','Giao dịch'],['customers','Khách hàng'],['reports','Báo cáo'],['settings','Thêm']];
const names=Object.fromEntries(navItems);
let route='overview',customerId=1,query='',status='all',type='all',reportCustomer='all';
const customer=id=>customers.find(c=>c.id===Number(id));
const date=s=>s.split('-').reverse().join('/');
const sums=rows=>rows.reduce((s,t)=>({principal:s.principal+t.amount,interest:s.interest+t.interest,total:s.total+t.amount+t.interest}),{principal:0,interest:0,total:0});
const debt=id=>sums(transactions.filter(t=>!t.paid&&(!id||t.c===id)));
const badge=t=>`<span class="badge ${t.paid?'paid':''}">${t.paid?'Đã thanh toán':'Chưa thanh toán'}</span>`;
const addButton=()=>`<button class="primary" data-action="add">${icon('plus')}Thêm giao dịch</button>`;
function heading(title,subtitle,actions=''){return `<div class="heading"><div><div class="eyebrow">SỔ CÔNG NỢ / 2026</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function stats(d=debt()){return `<div class="stats"><div class="stat featured"><div class="label">Tổng cần thu ${icon('wallet')}</div><strong class="amount">${money(d.total)}<em>₫</em></strong><small>Gốc + lãi chưa thanh toán</small></div><div class="stat"><div class="label">Dư nợ gốc ${icon('transactions')}</div><strong class="amount">${money(d.principal)}<em>₫</em></strong><small>Các giao dịch đang mở</small></div><div class="stat"><div class="label">Lãi cần thu ${icon('reports')}</div><strong class="amount">${money(d.interest)}<em>₫</em></strong><small>Tạm tính đến 02/11/2026</small></div></div>`;}
function txTable(rows){if(!rows.length)return '<div class="panel empty">Không tìm thấy giao dịch phù hợp.<br><small>Thử từ khóa khác hoặc chọn tất cả trạng thái.</small></div>';return `<div class="panel"><div class="desktop-table"><table><thead><tr><th>NGÀY / MÃ</th><th>KHÁCH HÀNG / NỘI DUNG</th><th class="num">TIỀN GỐC</th><th class="num">LÃI</th><th>TRẠNG THÁI</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${date(t.date)}<small>#GD${t.id}</small></td><td><button class="link" data-detail="${t.c}">${esc(customer(t.c).name)}</button><small>${esc(t.content)}</small><small>${esc(t.type)}</small></td><td class="num money">${money(t.amount)}</td><td class="num money">${money(t.interest)}</td><td>${badge(t)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-list">${rows.map(t=>`<article class="tx-card"><div class="card-top"><button class="link" data-detail="${t.c}">${esc(customer(t.c).name)}</button>${badge(t)}</div><div class="card-meta">${date(t.date)} · #GD${t.id} · ${esc(t.type)}</div><p>${esc(t.content)}</p><div class="card-bottom"><div><small>Tiền gốc</small><strong class="money">${money(t.amount)} ₫</strong></div><div class="right"><small>Lãi</small><b>${money(t.interest)} ₫</b></div></div></article>`).join('')}</div><div class="table-foot">${rows.length} giao dịch · Đơn vị: VNĐ</div></div>`;}
function overview(){const active=customers.filter(c=>debt(c.id).total>0);return heading('Tổng quan','Thứ Hai, 02 tháng 11 · Chào buổi sáng, Minh An',addButton())+stats()+`<div class="columns"><section class="panel"><div class="panel-head"><div><h2>Khách hàng còn công nợ</h2><small>${active.length} khách hàng cần theo dõi</small></div><a href="#customers">Xem tất cả ↗</a></div>${active.sort((a,b)=>debt(b.id).total-debt(a.id).total).map(c=>`<div class="row"><span class="avatar">${c.initials}</span><div class="grow"><button class="link" data-detail="${c.id}">${c.name}</button><small>${transactions.filter(t=>t.c===c.id&&!t.paid).length} giao dịch đang mở</small></div><strong class="money">${money(debt(c.id).total)} ₫</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Cơ cấu dư nợ gốc</h2></div><div class="panel-body">${['Tiền mặt','Chuyển khoản','Mua hàng'].map(type=>{const n=sums(transactions.filter(t=>!t.paid&&t.type===type)).principal;return `<div class="summary-line"><span>${type}</span><b>${money(n)} ₫</b></div><div class="bar"><span style="width:${debt().principal?n/debt().principal*100:0}%"></span></div>`;}).join('')}<div class="note">Số liệu của năm 2026. Chạm vào tên khách hàng để xem chi tiết tiền gốc, lãi và từng giao dịch.</div></div></section></div><div class="panel-head"><h2>Giao dịch gần đây</h2><a href="#transactions">Xem tất cả ↗</a></div>${txTable(transactions.slice(0,3))}`;}
function filters(withType=true){return `<div class="toolbar"><div class="search">${icon('search')}<input id="search" type="search" placeholder="${route==='customers'?'Tìm tên hoặc số điện thoại…':'Tìm khách hàng, nội dung, mã giao dịch…'}" aria-label="Tìm kiếm" value="${esc(query)}"></div>${withType?`<select id="type" aria-label="Loại giao dịch"><option value="all">Tất cả loại giao dịch</option>${['Tiền mặt','Chuyển khoản','Mua hàng'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select>`:''}</div><div class="chips" aria-label="Lọc trạng thái">${[['all','Tất cả'],['open','Chưa thanh toán'],['paid','Đã thanh toán']].map(([key,label])=>`<button data-filter="${key}" class="chip ${status===key?'selected':''}" aria-pressed="${status===key}">${label}</button>`).join('')}</div>`;}
function filteredTransactions(){const q=query.toLocaleLowerCase('vi');return transactions.filter(t=>(status==='all'||(status==='paid')===t.paid)&&(type==='all'||type===t.type)&&`${customer(t.c).name} ${t.content} GD${t.id}`.toLocaleLowerCase('vi').includes(q));}
function transactionPage(){return heading('Giao dịch','Theo dõi tiền gốc, lãi và trạng thái thanh toán',addButton())+filters()+`<div id="results">${txTable(filteredTransactions())}</div>`;}
function customerResults(){const q=query.toLocaleLowerCase('vi');const rows=customers.filter(c=>`${c.name} ${c.phone}`.toLocaleLowerCase('vi').includes(q)&&(status==='all'||(status==='open'?debt(c.id).total>0:debt(c.id).total===0)));if(!rows.length)return '<div class="panel empty">Không tìm thấy khách hàng.<small>Thử tìm theo tên hoặc số điện thoại khác.</small></div>';return `<div class="panel">${rows.map(c=>`<div class="row"><span class="avatar">${c.initials}</span><div class="grow"><button class="link" data-detail="${c.id}">${c.name}</button><small>${c.phone}</small><small>${c.address}</small></div><div class="right"><strong class="money">${money(debt(c.id).total)} ₫</strong><small>${debt(c.id).total?'Cần thu':'Đã tất toán'}</small></div></div>`).join('')}<div class="table-foot">${rows.length} khách hàng · Chạm vào tên để xem công nợ</div></div>`;}
function customerPage(){return heading('Khách hàng','Tra cứu nhanh công nợ và lịch sử giao dịch')+stats()+filters(false)+`<div id="results">${customerResults()}</div>`;}
function detail(){const c=customer(customerId),d=debt(c.id);return `<a class="back" href="#customers">${icon('back')}Danh sách khách hàng</a>`+heading(c.name,`${c.phone} · ${c.address}`,addButton())+`<section class="panel"><div class="panel-head"><h2>Công nợ của khách hàng</h2><span class="badge ${d.total?'':'paid'}">${d.total?'Còn công nợ':'Đã tất toán'}</span></div><div class="panel-body detail-summary"><div><span>Dư nợ gốc</span><strong>${money(d.principal)} ₫</strong></div><div><span>Lãi cần thu</span><strong>${money(d.interest)} ₫</strong></div><div><span>Ngày chốt công nợ</span><strong>02/11/2026</strong></div></div><div class="detail-total"><span>Tổng cần thanh toán</span><strong class="money">${money(d.total)} ₫</strong></div></section><div class="toolbar"><button data-action="report-customer">${icon('reports')}Xem báo cáo khách hàng</button></div><div class="panel-head"><h2>Lịch sử giao dịch</h2><small>Toàn bộ giao dịch năm 2026</small></div>${txTable(transactions.filter(t=>t.c===c.id))}`;}
function reportBody(){const rows=customers.filter(c=>reportCustomer==='all'||c.id===Number(reportCustomer));const d=sums(transactions.filter(t=>!t.paid&&(reportCustomer==='all'||t.c===Number(reportCustomer))));return `<div class="panel"><div class="report-title"><div class="eyebrow">HỘ KINH DOANH MINH AN</div><h2>BÁO CÁO CÔNG NỢ</h2><p>Đến ngày 02/11/2026 · Năm làm việc 2026</p><small>Dữ liệu minh họa · Đơn vị: VNĐ</small></div><div class="desktop-table"><table><thead><tr><th>KHÁCH HÀNG</th><th class="num">NỢ GỐC</th><th class="num">TIỀN LÃI</th><th class="num">TỔNG CẦN THU</th></tr></thead><tbody>${rows.map(c=>{const d=debt(c.id);return `<tr><td>${c.name}</td><td class="num money">${money(d.principal)}</td><td class="num money">${money(d.interest)}</td><td class="num money">${money(d.total)}</td></tr>`;}).join('')}</tbody></table></div><div class="mobile-list">${rows.map(c=>{const d=debt(c.id);return `<div class="tx-card"><h3>${c.name}</h3><div class="card-bottom"><small>Gốc ${money(d.principal)}<br>Lãi ${money(d.interest)}</small><strong class="money">${money(d.total)} ₫</strong></div></div>`;}).join('')}</div><div class="detail-total"><span>Tổng cộng</span><strong>${money(d.total)} ₫</strong></div></div>`;}
function reports(){return heading('Báo cáo công nợ','Đối chiếu số dư theo khách hàng',`<button data-action="print">${icon('print')}In / Lưu PDF</button>`)+`<div class="toolbar"><label for="report-customer">Khách hàng</label><select id="report-customer"><option value="all">Tất cả khách hàng</option>${customers.map(c=>`<option value="${c.id}" ${String(c.id)===reportCustomer?'selected':''}>${c.name}</option>`).join('')}</select></div><div id="report-result">${reportBody()}</div><p class="note">Lãi trong prototype là số liệu mẫu, không thực hiện tính lãi nghiệp vụ. Nút In / Lưu PDF mở chức năng in của trình duyệt.</p>`;}
function settings(){return heading('Thêm','Thông tin làm việc và các cấu hình tham khảo')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Không gian làm việc</h2></div><div class="settings-row"><div><b>Hộ kinh doanh Minh An</b><small>Tài khoản: Chủ cửa hàng</small></div><span class="avatar">MA</span></div><div class="settings-row"><span>Năm làm việc</span><b>2026</b></div><div class="settings-row"><span>Đơn vị tiền tệ</span><b>VNĐ</b></div></section><section class="panel"><div class="panel-head"><h2>Lãi suất tham khảo</h2></div>${[['Tiền mặt','2% / tháng'],['Chuyển khoản','2% / tháng'],['Mua hàng','1,5% / tháng']].map(([a,b])=>`<div class="settings-row"><span>${a}</span><b>${b}</b></div>`).join('')}</section></div><div class="note">Bản duyệt giao diện 01. Có thể thử điều hướng, tìm kiếm, lọc, xem công nợ và thêm giao dịch. Dữ liệu chỉ giữ trong phiên đang mở; tải lại trang để trở về dữ liệu ban đầu.</div>`;}
function render(){document.querySelector('#crumb').textContent=route==='detail'?'Chi tiết công nợ':names[route];const nav=navItems.map(([id,label])=>`<a href="#${id}" title="${label}" class="${route===id||(id==='customers'&&route==='detail')?'active':''}" ${route===id||(id==='customers'&&route==='detail')?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('');document.querySelector('#side-nav').innerHTML=nav;document.querySelector('#bottom-nav').innerHTML=nav;document.querySelector('#content').innerHTML=({overview,transactions:transactionPage,customers:customerPage,detail,reports,settings}[route]||overview)();}
function readRoute(){const [name,id]=location.hash.slice(1).split('/');route=names[name]||name==='detail'?name:'overview';if(route==='detail'){customerId=Number(id);if(!customer(customerId))route='customers';}query='';status='all';type='all';render();window.scrollTo(0,0);}
window.addEventListener('hashchange',readRoute);
let toastTimer;
function toast(text){const node=document.querySelector('#toast');node.textContent=text;node.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.style.display='none',3500);}
function openForm(){const modal=document.querySelector('#modal');modal.innerHTML=`<div class="dialog-head"><div><small>GIAO DỊCH MỚI</small><h2 id="dialog-title">Thêm giao dịch</h2></div><button data-action="close" aria-label="Đóng form">✕</button></div><form id="transaction-form"><div class="form-note">Giao dịch được thêm vào bản mẫu. Không gửi dữ liệu lên hệ thống.</div><div class="fields"><label class="full">Khách hàng *<select name="customer" required>${customers.map(c=>`<option value="${c.id}" ${route==='detail'&&c.id===customerId?'selected':''}>${c.name} · ${c.phone}</option>`).join('')}</select></label><label>Ngày giao dịch *<input name="date" type="date" value="2026-11-02" max="2026-11-02" min="2026-01-01" required></label><label>Loại giao dịch *<select name="type"><option>Mua hàng</option><option>Tiền mặt</option><option>Chuyển khoản</option></select></label><label class="full">Số tiền gốc (VNĐ) *<input name="amount" type="number" inputmode="numeric" min="1000" max="999999999999" step="1000" placeholder="Ví dụ: 5.000.000" required></label><label class="full">Nội dung giao dịch *<textarea name="content" rows="3" maxlength="300" placeholder="Nhập hàng hóa, khoản vay hoặc ghi chú…" required></textarea></label><label class="full">Ảnh chứng từ <small>Tùy chọn · Chỉ xem tên tệp trong bản mẫu</small><input name="attachment" type="file" accept="image/*"></label></div><p><small>Lãi hiển thị bằng 0 cho giao dịch mới trong bản mẫu.</small></p><div class="form-actions"><button type="button" data-action="close">Hủy</button><button class="primary" type="submit">Lưu giao dịch mẫu</button></div></form>`;modal.showModal();}
document.addEventListener('click',e=>{const detailButton=e.target.closest('[data-detail]');if(detailButton){location.hash=`detail/${detailButton.dataset.detail}`;return;}const filter=e.target.closest('[data-filter]');if(filter){status=filter.dataset.filter;render();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='add')openForm();if(action==='close')document.querySelector('#modal').close();if(action==='print')window.print();if(action==='report-customer'){reportCustomer=String(customerId);location.hash='reports';}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#results').innerHTML=route==='customers'?customerResults():txTable(filteredTransactions());}});
document.addEventListener('change',e=>{if(e.target.id==='type'){type=e.target.value;document.querySelector('#results').innerHTML=txTable(filteredTransactions());}if(e.target.id==='report-customer'){reportCustomer=e.target.value;document.querySelector('#report-result').innerHTML=reportBody();}});
document.addEventListener('submit',e=>{if(e.target.id!=='transaction-form')return;e.preventDefault();const f=new FormData(e.target);const content=String(f.get('content')).trim();if(!content){e.target.elements.content.setCustomValidity('Vui lòng nhập nội dung giao dịch.');e.target.elements.content.reportValidity();e.target.elements.content.oninput=()=>e.target.elements.content.setCustomValidity('');return;}transactions.unshift({id:Math.max(...transactions.map(t=>t.id))+1,c:Number(f.get('customer')),date:String(f.get('date')),type:String(f.get('type')),content,amount:Number(f.get('amount')),interest:0,paid:false});document.querySelector('#modal').close();query='';status='all';type='all';if(route==='transactions')render();else location.hash='transactions';toast('Đã thêm giao dịch vào bản mẫu.');});
readRoute();
